//! Port of graph-wiring-epiplexity `tests/test_engine.py` (package
//! `epiplexity` v0.5.0): arithmetic invariants of the epiplexity engine,
//! per `docs/specs/09-spectral-array.md` (normative scope).

use smartcore_orchestrator::{EpiplexityEngine, EpiplexityModel, Verdict};

/// Trivial deterministic model: fixed log-prob and fixed description
/// length; 64 bits per dataset item as the raw baseline.
struct ConstantModel {
    desc_bits: f64,
    lp: f64,
}

impl EpiplexityModel for ConstantModel {
    fn description_length_bits(&self) -> f64 {
        self.desc_bits
    }
    fn log_prob(&self, _item: &[f64]) -> f64 {
        self.lp
    }
    fn raw_bits(&self, dataset: &[&[f64]]) -> f64 {
        (dataset.len() * 64) as f64
    }
}

fn dataset(n_items: usize, dim: usize) -> Vec<Vec<f64>> {
    vec![vec![0.0; dim]; n_items]
}

#[test]
fn structural_bits_equals_description_length() {
    let model = ConstantModel { desc_bits: 2048.0, lp: -2.0 };
    let rows = dataset(10, 4);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    assert_eq!(engine.structural_bits(), 2048.0);
}

#[test]
fn entropy_bits_shape_matches_dataset() {
    let model = ConstantModel { desc_bits: 1024.0, lp: -2.0 };
    let rows = dataset(7, 3);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    assert_eq!(engine.entropy_bits().len(), 7);
}

#[test]
fn entropy_bits_are_positive_when_log_prob_negative() {
    let model = ConstantModel { desc_bits: 1024.0, lp: -3.0 };
    let rows = dataset(5, 2);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    assert!(engine.entropy_bits().iter().all(|&h| h > 0.0));
}

#[test]
fn per_item_entropy_formula() {
    let model = ConstantModel { desc_bits: 1024.0, lp: -4.0 };
    let rows = dataset(5, 2);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    let expected = -(-4.0) / std::f64::consts::LN_2;
    assert!(engine.entropy_bits().iter().all(|&h| (h - expected).abs() < 1e-12));
}

#[test]
fn total_entropy_is_sum_of_per_item_bits() {
    let model = ConstantModel { desc_bits: 1024.0, lp: -1.0 };
    let rows = dataset(8, 2);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    let sum: f64 = engine.entropy_bits().sum();
    assert!((engine.total_entropy_bits() - sum).abs() < 1e-9);
}

#[test]
fn mdl_total_is_structural_plus_entropy() {
    let model = ConstantModel { desc_bits: 512.0, lp: -2.0 };
    let rows = dataset(6, 2);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    let expected = engine.structural_bits() + engine.total_entropy_bits();
    assert!((engine.mdl_total_bits() - expected).abs() < 1e-9);
}

#[test]
fn compression_ratio_formula() {
    let model = ConstantModel { desc_bits: 1024.0, lp: -2.0 };
    let rows = dataset(10, 4);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    let expected = model.raw_bits(&refs) / engine.mdl_total_bits();
    assert!((engine.compression_ratio() - expected).abs() < 1e-9);
}

#[test]
fn structural_verdict_when_mdl_below_raw() {
    // desc=10, log_prob=-1e-3 -> MDL ~= 10.014 << raw=640.
    let model = ConstantModel { desc_bits: 10.0, lp: -0.001 };
    let rows = dataset(10, 4);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    assert_eq!(engine.verdict(), Verdict::Structural);
    assert!(engine.compression_ratio() > 1.0);
}

#[test]
fn metadata_verdict_when_mdl_above_raw() {
    // desc=10000, log_prob=-1 -> MDL ~= 10014.4 > raw=640.
    let model = ConstantModel { desc_bits: 10_000.0, lp: -1.0 };
    let rows = dataset(10, 4);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    assert_eq!(engine.verdict(), Verdict::Metadata);
    assert!(engine.compression_ratio() < 1.0);
}

#[test]
fn report_contains_sections_and_verdict_word() {
    let model = ConstantModel { desc_bits: 1024.0, lp: -2.0 };
    let rows = dataset(10, 4);
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    let report = engine.report();
    for section in ["Structural bits", "Random bits", "Compression ratio", "Verdict"] {
        assert!(report.contains(section), "report missing '{section}':\n{report}");
    }
    assert!(
        report.contains("STRUCTURAL") || report.contains("METADATA"),
        "report missing verdict word:\n{report}"
    );
}

#[test]
fn single_item_dataset_edge_case() {
    // Property-suite P6 edge case: one item only.
    struct FixedModel;
    impl EpiplexityModel for FixedModel {
        fn description_length_bits(&self) -> f64 {
            100.0
        }
        fn log_prob(&self, _item: &[f64]) -> f64 {
            -5.0
        }
        fn raw_bits(&self, dataset: &[&[f64]]) -> f64 {
            dataset.len() as f64 * 64.0
        }
    }
    let row = [42.0];
    let refs: Vec<&[f64]> = vec![row.as_slice()];
    let engine = EpiplexityEngine::new(&FixedModel, &refs);
    assert_eq!(engine.entropy_bits().len(), 1);
    assert!((engine.total_entropy_bits() - engine.entropy_bits()[0]).abs() < 1e-12);
    let expected_mdl = 100.0 + 5.0 / std::f64::consts::LN_2;
    assert!((engine.mdl_total_bits() - expected_mdl).abs() < 1e-12);
}

//! Epiplexity engine — Rust port of graph-wiring-epiplexity
//! `epiplexity/engine.py` + `epiplexity/model.py` (package `epiplexity`
//! v0.5.0), normative scope per `docs/specs/09-spectral-array.md`.

use std::f64::consts::LN_2;

/// Port of the Python `TTimeProbabilisticModel` ABC.
///
/// Deliberate deviation: the Python ABC's `sample(n)` is omitted. No RNG
/// enters scheduling paths (house determinism law); deterministic probe
/// starts replace generative sampling in phase 1.
pub trait EpiplexityModel {
    /// S_T(X): description length in bits of this model/program,
    /// including hyperparameters, initialisation, and learned state.
    fn description_length_bits(&self) -> f64;

    /// log P(x) in natural logs for one item.
    fn log_prob(&self, item: &[f64]) -> f64;

    /// Baseline uncompressed size of the dataset in bits.
    fn raw_bits(&self, dataset: &[&[f64]]) -> f64;
}

/// Two-part-code verdict: STRUCTURAL iff MDL_T < raw bits.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verdict {
    Structural,
    Metadata,
}

impl Verdict {
    pub fn as_str(self) -> &'static str {
        match self {
            Verdict::Structural => "STRUCTURAL",
            Verdict::Metadata => "METADATA",
        }
    }
}

/// Port of `EpiplexityEngine`: generic epiplexity and time-bounded
/// entropy calculator over any [`EpiplexityModel`].
pub struct EpiplexityEngine<'a, M: EpiplexityModel> {
    model: &'a M,
    dataset: &'a [&'a [f64]],
    entropy_bits: Vec<f64>,
}

impl<'a, M: EpiplexityModel> EpiplexityEngine<'a, M> {
    /// Computes per-item log-probabilities and entropies (in bits).
    pub fn new(model: &'a M, dataset: &'a [&'a [f64]]) -> Self {
        let entropy_bits = dataset
            .iter()
            .map(|x| -model.log_prob(x) / LN_2)
            .collect();
        Self { model, dataset, entropy_bits }
    }

    /// Epiplexity proxy S_T(X): model/program bits.
    pub fn structural_bits(&self) -> f64 {
        self.model.description_length_bits()
    }

    /// Per-item time-bounded entropy H_T(x_i) in bits.
    pub fn entropy_bits(&self) -> &[f64] {
        &self.entropy_bits
    }

    /// H_T(X): sum of per-item random-information bits.
    pub fn total_entropy_bits(&self) -> f64 {
        self.entropy_bits.iter().sum()
    }

    /// Two-part MDL code length: S_T(X) + H_T(X).
    pub fn mdl_total_bits(&self) -> f64 {
        self.structural_bits() + self.total_entropy_bits()
    }

    /// raw / MDL: > 1 means non-trivial structure.
    pub fn compression_ratio(&self) -> f64 {
        self.model.raw_bits(self.dataset) / self.mdl_total_bits()
    }

    pub fn verdict(&self) -> Verdict {
        if self.mdl_total_bits() < self.model.raw_bits(self.dataset) {
            Verdict::Structural
        } else {
            Verdict::Metadata
        }
    }

    /// Formatted report mirroring the Python engine's printout.
    pub fn report(&self) -> String {
        let kb = |bits: f64| bits / (8.0 * 1024.0);
        let verdict = match self.verdict() {
            Verdict::Structural => "STRUCTURAL",
            Verdict::Metadata => "METADATA",
        };
        format!(
            "Epiplexity report\n\
             -----------------\n\
             \x20 Structural bits S_T     : {:8.2} KB\n\
             \x20 Random bits H_T         : {:8.2} KB\n\
             \x20 Total MDL S_T + H_T     : {:8.2} KB\n\
             \x20 Raw size                : {:8.2} KB\n\
             \x20 Compression ratio       : {:8.2}x\n\
             \x20 Verdict                 : {}\n",
            kb(self.structural_bits()),
            kb(self.total_entropy_bits()),
            kb(self.mdl_total_bits()),
            kb(self.model.raw_bits(self.dataset)),
            self.compression_ratio(),
            verdict,
        )
    }
}

