//! Port of the arrowspace/LGMRF parts of graph-wiring-epiplexity
//! `tests/test_epiplexity_properties.py` (package `epiplexity` v0.5.0):
//! property obligations P1, P2, P3, P4-analog, P6 and the
//! Dirichlet-energy <-> H_T monotonicity check, per
//! `docs/specs/09-spectral-array.md`.

use smartcore_orchestrator::{EpiplexityEngine, EpiplexityModel, Lgmrf};
use sprs::{CsMat, TriMat};

const BETA: f64 = 1.0;
const GAMMA: f64 = 1e-3;
const C0: usize = 32;
const K: usize = 4;
const B: u32 = 32;

/// Combinatorial Laplacian of a path graph on `f` nodes (fixture of the
/// Python property suite: `_make_path_laplacian`).
fn path_laplacian(f: usize) -> CsMat<f64> {
    let mut tri = TriMat::with_capacity((f, f), 3 * f);
    for i in 0..f {
        let degree = match i {
            0 | f_ if f_ == f - 1 => 1.0,
            _ => 2.0,
        };
        tri.add_triplet(i, i, degree);
    }
    for i in 0..f - 1 {
        tri.add_triplet(i, i + 1, -1.0);
        tri.add_triplet(i + 1, i, -1.0);
    }
    tri.to_csr()
}

/// Deterministic fixture signals on F dims: smooth (constant) vs rough
/// (alternating), both unit-norm — mirrors the P7 fixture.
fn smooth_and_rough(f: usize) -> (Vec<f64>, Vec<f64>) {
    let s = (f as f64).sqrt();
    let smooth: Vec<f64> = vec![1.0 / s; f];
    let rough: Vec<f64> = (0..f).map(|i| (-1.0f64).powi(i as i32) / s).collect();
    (smooth, rough)
}

fn basin_model(f: usize) -> Lgmrf {
    Lgmrf::new(&path_laplacian(f), BETA, GAMMA, C0, K, B)
}

#[test]
fn mdl_identity_holds_on_basin_model() {
    let model = basin_model(16);
    let rows: Vec<Vec<f64>> = (0..20)
        .map(|i| std::iter::repeat(i as f64).take(16).collect())
        .collect();
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    let expected = engine.structural_bits() + engine.total_entropy_bits();
    assert!((engine.mdl_total_bits() - expected).abs() < 1e-9 * expected.abs().max(1.0));
}

#[test]
fn entropy_non_negative_and_finite() {
    let model = basin_model(16);
    let rows: Vec<Vec<f64>> = (0..12)
        .map(|i| (0..16).map(|j| ((i * 16 + j) % 7) as f64 - 3.0).collect())
        .collect();
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    assert!(engine
        .entropy_bits()
        .iter()
        .all(|&h| h.is_finite() && h >= -1e-9));
}

#[test]
fn compression_ratio_positive_for_all_items() {
    let model = basin_model(16);
    let rows: Vec<Vec<f64>> = (0..10).map(|i| vec![i as f64; 16]).collect();
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    assert!(engine.compression_ratio() > 0.0);
}

#[test]
fn per_item_entropy_count_matches_dataset_length() {
    let model = basin_model(16);
    let rows: Vec<Vec<f64>> = (0..13).map(|i| vec![i as f64; 16]).collect();
    let refs: Vec<&[f64]> = rows.iter().map(|r| r.as_slice()).collect();
    let engine = EpiplexityEngine::new(&model, &refs);
    assert_eq!(engine.entropy_bits().len(), refs.len());
}

#[test]
fn smooth_signal_has_lower_entropy_than_rough() {
    // LGMRF theorem: H_T tracks Dirichlet energy x^T L x.
    let model = basin_model(16);
    let (smooth, rough) = smooth_and_rough(16);
    let ht_smooth = -model.log_prob(&smooth) / std::f64::consts::LN_2;
    let ht_rough = -model.log_prob(&rough) / std::f64::consts::LN_2;
    assert!(
        ht_smooth < ht_rough,
        "smooth H_T={ht_smooth:.4} must be < rough H_T={ht_rough:.4}"
    );
}

#[test]
fn structural_bits_monotone_in_k() {
    let model = basin_model(16);
    let st: Vec<f64> = [2usize, 4, 8, 16]
        .into_iter()
        .map(|k| {
            Lgmrf::new(&path_laplacian(16), BETA, GAMMA, C0, k, B).description_length_bits()
        })
        .collect();
    let mut sorted = st.clone();
    sorted.sort_by(|a, b| a.total_cmp(b));
    assert_eq!(st, sorted, "S_T not monotonically increasing with k");
    let _ = model;
}

#[test]
fn structural_bits_monotone_in_c0() {
    let st: Vec<f64> = [8usize, 16, 32, 64]
        .into_iter()
        .map(|c0| {
            Lgmrf::new(&path_laplacian(16), BETA, GAMMA, c0, K, B).description_length_bits()
        })
        .collect();
    let mut sorted = st.clone();
    sorted.sort_by(|a, b| a.total_cmp(b));
    assert_eq!(st, sorted, "S_T not monotonically increasing with C0");
}

