//! Basin LGMRF model — Rust port of graph-wiring-epiplexity's
//! ArrowSpace probabilistic model (`_MinimalArrowSpaceModel` +
//! `ArrowSpaceModelAdapter`, package `epiplexity` v0.5.0), normative
//! scope per `docs/specs/09-spectral-array.md`.

use std::f64::consts::{LN_2, PI};

use sprs::{CsMat, TriMat};

use crate::spectral_array::epiplexity::EpiplexityModel;

/// Laplacian-constrained Gaussian Markov random field over one basin:
/// precision `Q = beta * L + gamma * I`, `gamma > 0` makes Q positive
/// definite for any PSD operator.
pub struct Lgmrf {
    f: usize,
    q: CsMat<f64>,
    log_z: f64,
    c0: usize,
    k: usize,
    b: u32,
}

impl Lgmrf {
    /// Builds the precision matrix and the normalisation constant.
    ///
    /// The determinant uses a dense Cholesky on the normative path only;
    /// it never runs inside a scheduling signal.
    pub fn new(laplacian: &CsMat<f64>, beta: f64, gamma: f64, c0: usize, k: usize, b: u32) -> Self {
        let f = laplacian.rows();
        let scaled = laplacian.map(|v| v * beta);
        let mut ridge = TriMat::with_capacity((f, f), f);
        for i in 0..f {
            ridge.add_triplet(i, i, gamma);
        }
        let q = &scaled + &ridge.to_csr();

        let mut dense = vec![0.0f64; f * f];
        for (i, row) in q.outer_iterator().enumerate() {
            for (j, val) in row.iter() {
                dense[i * f + j] = val;
            }
        }
        let log_det_q = log_det_spd(&mut dense, f);
        let log_z = 0.5 * f as f64 * (2.0 * PI).ln() - 0.5 * log_det_q;

        Self { f, q, log_z, c0, k, b }
    }

    pub fn dim(&self) -> usize {
        self.f
    }

    /// log P(x) = -1/2 x^T Q x - log Z, natural logs.
    pub fn log_prob(&self, x: &[f64]) -> f64 {
        debug_assert_eq!(x.len(), self.f);
        -0.5 * quad_form(&self.q, x) - self.log_z
    }

    /// Structural bits of the basin-operator coding (PAS formula):
    /// Elias-gamma header over `[F, C0, k]`, fixed parameter block,
    /// centroid matrix, and topology edge list.
    pub fn description_length_bits(&self) -> f64 {
        let header: f64 = [self.f as u64, self.c0 as u64, self.k as u64]
            .into_iter()
            .map(elias_gamma_bits)
            .sum();
        let params = 64.0 + 8.0 + 32.0;
        let centroids = self.c0 as f64 * self.f as f64 * self.b as f64;
        let topology = self.k as f64
            * self.f as f64
            * ((self.f.max(2) as f64).log2().ceil() + self.b as f64);
        header + params + centroids + topology
    }
}

/// Port of `ArrowSpaceModelAdapter` semantics onto [`EpiplexityModel`].
impl EpiplexityModel for Lgmrf {
    fn description_length_bits(&self) -> f64 {
        Lgmrf::description_length_bits(self)
    }

    fn log_prob(&self, item: &[f64]) -> f64 {
        Lgmrf::log_prob(self, item)
    }

    fn raw_bits(&self, dataset: &[&[f64]]) -> f64 {
        dataset.len() as f64 * self.f as f64 * self.b as f64
    }
}

fn elias_gamma_bits(x: u64) -> f64 {
    2.0 * (x.max(1) as f64).log2().floor() + 1.0
}

fn quad_form(q: &CsMat<f64>, x: &[f64]) -> f64 {
    let mut acc = 0.0;
    for (row_idx, row) in q.outer_iterator().enumerate() {
        let mut dot = 0.0;
        for (col, val) in row.iter() {
            dot += val * x[col];
        }
        acc += x[row_idx] * dot;
    }
    acc
}

/// In-place Cholesky LL^T on a row-major SPD matrix; returns ln det.
fn log_det_spd(a: &mut [f64], n: usize) -> f64 {
    let mut log_det = 0.0;
    for i in 0..n {
        for j in 0..=i {
            let mut s = a[i * n + j];
            for k in 0..j {
                s -= a[i * n + k] * a[j * n + k];
            }
            if i == j {
                assert!(s > 0.0, "precision matrix is not positive definite");
                let d = s.sqrt();
                a[i * n + j] = d;
                log_det += d.ln();
            } else {
                a[i * n + j] = s / a[j * n + j];
            }
        }
    }
    2.0 * log_det
}

