//! Trailblazer ordering policy obligations, per `docs/specs/09-spectral-array.md`:
//! score-descending, ties by lowest id, pure function of the scores.

use smartcore_orchestrator::trailblazer_order;

#[test]
fn orders_descending_by_score() {
    let scores = vec![(0usize, 1.5), (1, 3.0), (2, 0.25), (3, 2.0)];
    assert_eq!(trailblazer_order(&scores), vec![1, 3, 0, 2]);
}

#[test]
fn ties_break_by_lowest_id() {
    let scores = vec![(7usize, 2.0), (3, 2.0), (9, 2.0), (1, 5.0)];
    assert_eq!(trailblazer_order(&scores), vec![1, 3, 7, 9]);
}

#[test]
fn empty_input_yields_empty_order() {
    assert!(trailblazer_order(&[]).is_empty());
}

#[test]
fn single_lane_passthrough() {
    assert_eq!(trailblazer_order(&[(42, 0.0)]), vec![42]);
}

#[test]
fn ordering_is_a_pure_function_of_scores() {
    let scores = vec![(4usize, 1.0), (2, 2.0), (8, 1.0)];
    let first = trailblazer_order(&scores);
    let second = trailblazer_order(&scores);
    assert_eq!(first, second);
}

//! Trailblazer ordering — the epiplexity role as eigenpath
//! selector/trailblazer (`docs/specs/09-spectral-array.md`).

/// Orders lane/basin ids by estimated learnable structure, descending;
/// ties break by lowest id. A pure function of `scores`: no RNG enters
/// this path (house determinism law). Score values must be finite.
pub fn trailblazer_order(scores: &[(usize, f64)]) -> Vec<usize> {
    debug_assert!(
        scores.iter().all(|(_, s)| s.is_finite()),
        "trailblazer scores must be finite"
    );
    let mut order: Vec<usize> = (0..scores.len()).collect();
    order.sort_by(|&a, &b| {
        scores[b]
            .1
            .total_cmp(&scores[a].1)
            .then(scores[a].0.cmp(&scores[b].0))
    });
    order.into_iter().map(|i| scores[i].0).collect()
}

