//! Probe-based P^t residual-energy estimator obligations per
//! `docs/specs/09-spectral-array.md`: deterministic one-hot-lowest-index
//! evolution, retention ordering, and agreement with the normative LGMRF
//! two-part MDL on a fixture workload.

use smartcore_orchestrator::{
    EpiplexityEngine, Lgmrf, probe_score, residual_energy_decay, trailblazer_order,
};
use sprs::{CsMat, TriMat};

const BETA: f64 = 1.0;
const GAMMA: f64 = 1e-3;
const C0: usize = 32;
const K: usize = 4;
const B: u32 = 32;

/// Two cliques of size `m` joined by a single bridge edge; unit weights.
fn two_cliques(m: usize) -> CsMat<f64> {
    let f = 2 * m;
    let mut tri = TriMat::with_capacity((f, f), 2 * f * f);
    for i in 0..f {
        for j in 0..f {
            if i != j && i / m == j / m {
                tri.add_triplet(i, j, 1.0);
            }
        }
    }
    tri.add_triplet(m - 1, m, 1.0);
    tri.add_triplet(m, m - 1, 1.0);
    tri.to_csr()
}

/// Weighted complete graph with deterministic jittered weights: fast
/// mixing, no community structure.
fn complete_jittered(f: usize) -> CsMat<f64> {
    let mut tri = TriMat::with_capacity((f, f), f * f);
    for i in 0..f {
        for j in 0..f {
            if i != j {
                let w = 0.75 + 0.5 * (((i + 1) * (j + 3)) % 13) as f64 / 12.0;
                tri.add_triplet(i, j, w);
            }
        }
    }
    tri.to_csr()
}

#[test]
fn probe_starts_one_hot_at_lowest_index() {
    // E(delta_0) equals the degree of node 0 (each incident edge
    // contributes w * (1 - 0)^2).
    let lap = two_cliques(6);
    let profile = residual_energy_decay(&lap, 8);
    assert!((profile[0] - 5.0).abs() < 1e-12);
}

#[test]
fn energy_profile_is_deterministic() {
    let lap = two_cliques(6);
    let a = residual_energy_decay(&lap, 8);
    let b = residual_energy_decay(&lap, 8);
    assert_eq!(a, b);
}

#[test]
fn structured_basin_retains_more_probe_energy_than_fast_mixer() {
    let structured = two_cliques(6);
    let mixed = complete_jittered(12);
    assert!(
        probe_score(&structured) > probe_score(&mixed),
        "retention: structured={} mixed={}",
        probe_score(&structured),
        probe_score(&mixed)
    );
}

fn signals_structured(m: usize, rows: usize) -> Vec<Vec<f64>> {
    (0..rows)
        .map(|r| {
            (0..2 * m)
