//! Probe-based P^t statistics — the phase-1 scheduling estimator
//! (`docs/specs/09-spectral-array.md`). Deterministic Markov-chain
//! evolution of one-hot probes (P = D^-1 W, house law: probe starts at
//! the lowest-index member; seed 3407 is a non-factor because no
//! sampling exists on this path).

use sprs::CsMat;

/// Documented diffusion depth; a constant, not tuned.
pub const PROBE_HORIZON: usize = 8;

struct Walker {
    edges: Vec<(usize, usize, f64)>,
    out: Vec<Vec<(usize, f64)>>,
}

impl Walker {
    fn new(laplacian: &CsMat<f64>) -> Self {
        let f = laplacian.rows();
        let mut deg = vec![0.0f64; f];
        let mut edges = Vec::new();
        for (i, row) in laplacian.outer_iterator().enumerate() {
            for (j, val) in row.iter() {
                if i != j && *val < 0.0 {
                    let w = -*val;
                    deg[i] += w;
                    if i < j {
                        edges.push((i, j, w));
                    }
                }
            }
        }
        let mut out: Vec<Vec<(usize, f64)>> = vec![Vec::new(); f];
        for (i, row) in laplacian.outer_iterator().enumerate() {
            for (j, val) in row.iter() {
                if i != j && *val < 0.0 {
                    out[i].push((j, -*val / deg[i]));
                }
            }
        }
        Self { edges, out }
    }

    fn start_one_hot(&self) -> Vec<f64> {
        let mut v = vec![0.0f64; self.out.len()];
        v[0] = 1.0;
        v
    }

    /// Dirichlet energy of the probe distribution under W:
    /// sum over unordered edges of w_ij (v_i - v_j)^2.
    fn energy(&self, v: &[f64]) -> f64 {
        self.edges
            .iter()
            .map(|&(i, j, w)| w * (v[i] - v[j]).powi(2))
            .sum()
    }

    /// One step of P^T applied to a column distribution.
    fn step(&self, v: &[f64]) -> Vec<f64> {
        let mut nv = vec![0.0f64; v.len()];
        for (i, nbrs) in self.out.iter().enumerate() {
            let vi = v[i];
            for &(j, p) in nbrs {
                nv[j] += vi * p;
            }
        }
        nv
    }
}

/// Residual-energy profile E_0..E_horizon of the deterministic probe:
/// Dirichlet energy of the diffused one-hot distribution after each
/// step. Slow decay means coherent community structure retained under
/// diffusion; fast washout means structure-free mixing.
pub fn residual_energy_decay(laplacian: &CsMat<f64>, horizon: usize) -> Vec<f64> {
    let walker = Walker::new(laplacian);
    let mut v = walker.start_one_hot();
    let mut profile = Vec::with_capacity(horizon + 1);
    profile.push(walker.energy(&v));
    for _ in 0..horizon {
        v = walker.step(&v);
        profile.push(walker.energy(&v));
    }
    profile
}

/// Scheduling score: retained fraction E_horizon / E_0. Higher is more
/// structural (trailblazer schedules descending). An operator with no
/// edges retains nothing and scores 0.
pub fn probe_score(laplacian: &CsMat<f64>) -> f64 {
    let profile = residual_energy_decay(laplacian, PROBE_HORIZON);
    let e0 = profile[0];
    if e0 <= 0.0 {
        return 0.0;
    }
    profile[profile.len() - 1] / e0
}

