//! Ordering-stability matrix: the normative LGMRF two-part MDL and the
//! probe-based P^t retention estimator must agree on basin quality
//! across scale and topology (no inversions), per
//! `docs/specs/09-spectral-array.md` — both orderings land in the
//! comparison record.

mod common;

use common::{complete_jittered, signals_rough, signals_structured, two_cliques};
use smartcore_orchestrator::{EpiplexityEngine, Lgmrf, probe_score, trailblazer_order};
use sprs::CsMat;

const BETA: f64 = 1.0;
const GAMMA: f64 = 1e-3;
const C0: usize = 32;
const K: usize = 4;
const B: u32 = 32;
const ROWS: usize = 16;

fn normative_ratio(lap: &CsMat<f64>, signals: &[Vec<f64>]) -> f64 {
    let model = Lgmrf::new(lap, BETA, GAMMA, C0, K, B);
    let refs: Vec<&[f64]> = signals.iter().map(|s| s.as_slice()).collect();
    EpiplexityEngine::new(&model, &refs).compression_ratio()
}

#[test]
fn orderings_hold_across_scale_and_topology() {
    for f in [24usize, 96] {
        let structured_lap = two_cliques(f / 2);
        let rough_lap = complete_jittered(f);

        // Normative ordering: identical F/N/coding params per size.
        let r_structured = normative_ratio(&structured_lap, &signals_structured(f / 2, ROWS));
        let r_rough = normative_ratio(&rough_lap, &signals_rough(f, ROWS));
        assert!(
            r_structured > r_rough,
            "normative inverts at f={f}: {r_structured} vs {r_rough}"
        );

        // Probe ordering.
        let p_structured = probe_score(&structured_lap);
        let p_rough = probe_score(&rough_lap);
        assert!(
            p_structured > p_rough,
            "probe inverts at f={f}: {p_structured} vs {p_rough}"
        );

        // Identical trailblazer orderings land in the comparison record.
        assert_eq!(
            trailblazer_order(&[(0usize, r_structured), (1, r_rough)]),
            trailblazer_order(&[(0usize, p_structured), (1, p_rough)]),
            "orderings disagree at f={f}"
        );
    }
}

