/// the first-hop footprint E_1 (not E_0) makes the score
/// scale-invariant: E_0 grows with degree while post-mixing residual
/// energy shrinks as O(1/F^2), which would collapse large structured
/// basins toward zero. Higher is more structural (trailblazer schedules
/// descending). An operator with no edges retains nothing and scores 0.
pub fn probe_score(laplacian: &CsMat<f64>) -> f64 {
    let profile = residual_energy_decay(laplacian, PROBE_HORIZON);
    if profile.len() < 2 {
        return 0.0;
    }
    let e1 = profile[1];
    if e1 <= 0.0 {
        return 0.0;
    }
    profile[profile.len() - 1] / e1
}

