/// Scheduling score: retained fraction chi^2(v_T) / chi^2(v_1), the
/// decay of the probe's chi-square distance to the stationary
/// distribution pi = d / sum(d), normalized at the first-hop footprint.
///
/// This is a spectral-gap probe: bottlenecked basins retain chi^2 mass
/// across the horizon (escape probability ~ conductance per step),
/// while fast mixers collapse within a few hops. Normalizing by
/// chi^2(v_1) makes the score dimensionless and immune to basin scale;
/// measuring distance to stationarity (rather than raw Dirichlet
/// energy) keeps degree-heterogeneous but structure-free operators from
/// scoring high via their non-uniform stationary distribution.
///
/// Higher is more structural (trailblazer schedules descending). An
/// operator with no edges retains nothing and scores 0.
pub fn probe_score(laplacian: &CsMat<f64>) -> f64 {
    let walker = Walker::new(laplacian);
    let mut v = walker.start_one_hot();
    v = walker.step(&v);
    let c1 = walker.chi_square(&v);
    if c1 <= 0.0 {
        return 0.0;
    }
    for _ in 1..PROBE_HORIZON {
        v = walker.step(&v);
    }
    walker.chi_square(&v) / c1
}

