use sprs::TriMat;

/// Combinatorial Laplacian of two cliques of size `m` joined by a
/// single bridge edge; unit weights.
pub fn two_cliques(m: usize) -> CsMat<f64> {
    let f = 2 * m;
    let mut tri = TriMat::with_capacity((f, f), 2 * f * f);
    let mut deg = vec![0.0f64; f];
    for i in 0..f {
        for j in 0..f {
            if i != j && i / m == j / m {
                tri.add_triplet(i, j, -1.0);
                deg[i] += 1.0;
            }
        }
    }
    tri.add_triplet(m - 1, m, -1.0);
    tri.add_triplet(m, m - 1, -1.0);
    deg[m - 1] += 1.0;
    deg[m] += 1.0;
    for (i, d) in deg.iter().enumerate() {
        tri.add_triplet(i, i, *d);
    }
    tri.to_csr()
}

/// Combinatorial Laplacian of a weighted complete graph with
/// deterministic jittered weights: fast mixing, no community structure.
pub fn complete_jittered(f: usize) -> CsMat<f64> {
    let mut tri = TriMat::with_capacity((f, f), f * f);
    let mut deg = vec![0.0f64; f];
    for i in 0..f {
        for j in (i + 1)..f {
            let w = 0.75 + 0.5 * (((i + 1) * (j + 3)) % 13) as f64 / 12.0;
            tri.add_triplet(i, j, -w);
            tri.add_triplet(j, i, -w);
            deg[i] += w;
            deg[j] += w;
        }
    }
    for (i, d) in deg.iter().enumerate() {
        tri.add_triplet(i, i, *d);
    }
    tri.to_csr()
}

/// Combinatorial Laplacian of a path graph on `f` nodes.
pub fn path_laplacian(f: usize) -> CsMat<f64> {
    let mut tri = TriMat::with_capacity((f, f), 3 * f);
    for i in 0..f {
        let d = if i == 0 || i == f - 1 { 1.0 } else { 2.0 };
        tri.add_triplet(i, i, d);
        if i > 0 {
            tri.add_triplet(i - 1, i, -1.0);
            tri.add_triplet(i, i - 1, -1.0);
        }
    }
    tri.to_csr()
}

/// Clique-indicator signals with deterministic ripple: smooth under the
/// clique-basin operator.
pub fn signals_structured(m: usize, rows: usize) -> Vec<Vec<f64>> {
    (0..rows)
        .map(|r| {
            (0..2 * m)
                .map(|i| {
                    let base = if i < m { 1.0 } else { -1.0 };
                    base + 0.01 * ((r * 7 + i) % 5) as f64 - 0.02
                })
                .collect()
        })
        .collect()
}

/// Full-amplitude alternating signals: maximal Dirichlet energy on any
/// connected operator (phase shifts per row).
pub fn signals_rough(f: usize, rows: usize) -> Vec<Vec<f64>> {
    (0..rows)
        .map(|r| (0..f).map(|i| if (i + r) % 2 == 0 { 1.0 } else { -1.0 }).collect())
        .collect()
}

/// Linear ramp with row-dependent offset: smooth under the path
/// operator.
pub fn signals_ramp(f: usize, rows: usize) -> Vec<Vec<f64>> {
    (0..rows)
        .map(|r| (0..f).map(|i| 0.1 * i as f64 + 0.001 * r as f64).collect())
        .collect()
}

