//! Optimal-k basin-condensation obligations per
//! `docs/specs/09-spectral-array.md` §Basin condensation: the sequential
//! normative port of arrowspace 0.26.10 `OptimalKHeuristic` semantics.

use smartcore_orchestrator::{condense, compute_optimal_k};

/// Three tight blobs in `f` dimensions, centres on the first coordinate
/// axes; deterministic arithmetic offsets replace upstream RNG noise.
fn three_blobs(f: usize, per_cluster: usize) -> Vec<Vec<f64>> {
    let mut rows = Vec::new();
    for c in 0..3usize {
        for i in 0..per_cluster {
            let mut row = vec![0.0; f];
            if c < f {
                row[c] = 10.0;
            }
            for d in 0..f {
                row[d] += (((i * 7 + d * 3 + c * 5) % 11) as f64 - 5.0) * 0.02;
            }
            rows.push(row);
        }
    }
    rows
}

#[test]
fn three_blobs_find_three_basins() {
    let rows = three_blobs(10, 10);
    let ok = compute_optimal_k(&rows, 3407);
    assert_eq!(ok.k, 3, "expected k*=3, got {} (radius {})", ok.k, ok.radius);

    let basins = condense(&rows, 3407);
    assert_eq!(basins.assignments.len(), rows.len());
    assert_eq!(basins.centroids.len(), ok.k);
    for centroid in &basins.centroids {
        assert_eq!(centroid.len(), 10);
    }
    let mut counts = [0usize; 3];
    for &a in &basins.assignments {
        counts[a.min(2)] += 1;
    }
    for (c, &n) in counts.iter().enumerate() {
        assert!(n >= 5 && n <= 15, "cluster {c} has {n} points");
    }
    // Every point sits far nearer its own centroid than the others.
    for (row, &a) in rows.iter().zip(&basins.assignments) {
        let d = |cent: &[f64]| -> f64 {
            cent.iter()
                .zip(row)
                .map(|(x, y)| (x - y) * (x - y))
                .sum::<f64>()
                .sqrt()
        };
        let own = d(&basins.centroids[a as usize]);
        for (ci, cent) in basins.centroids.iter().enumerate() {
            if ci != a as usize {
                assert!(own <= d(cent), "point misassigned: {a} vs {ci}");
            }
        }
    }
}

#[test]
fn small_n_takes_the_bounds_floor() {
    // n = 6 < 10: the heuristic must short-circuit through the k_min
    // path; two separated groups make k = 2 both correct and trivially
    // reachable.
    let rows = vec![
        vec![0.0],
        vec![0.1],
        vec![0.2],
        vec![9.8],
        vec![9.9],
        vec![10.0],
    ];
    let ok = compute_optimal_k(&rows, 3407);
    assert_eq!(ok.k, 2);
    assert_eq!(ok.intrinsic_dim, 1, "n < 10 pins id to min(f, 2)");
}

#[test]
fn degenerate_identical_rows_stay_bounded() {
    let rows = vec![vec![1.0, 2.0]; 12];
    let ok = compute_optimal_k(&rows, 3407);
    assert_eq!(ok.k, 2, "zero-variance data collapses to k_min");
    assert!(ok.radius >= 1e-6, "radius floor applies: {}", ok.radius);

    let basins = condense(&rows, 3407);
    assert_eq!(basins.assignments.len(), 12);
}

#[test]
fn single_feature_separates_two_groups() {
    let rows = (0..20)
        .map(|i| {
            vec![if i < 10 {
                i as f64 * 0.1
            } else {
                10.0 + (i - 10) as f64 * 0.1
            }]
        })
        .collect::<Vec<_>>();
    let ok = compute_optimal_k(&rows, 3407);
    assert_eq!(ok.k, 2, "two linear runs must yield k=2, got {}", ok.k);
}

#[test]
fn high_dimensional_noise_stays_in_bounds() {
    let rows: Vec<Vec<f64>> = (0..40)
        .map(|i| {
            (0..50)
                .map(|d| ((i * 31 + d * 17) % 23) as f64 / 23.0 * 10.0)
                .collect()
        })
        .collect();
    let ok = compute_optimal_k(&rows, 3407);
    let k_min = (((rows.len() as f64) / 10.0).sqrt().ceil() as usize).max(2);
    let k_max = 2.min(rows.len() / 2).max(k_min + 1);
    let _ = k_max; // bound formula asserted via parity suite; here: sane output
    assert!(ok.k >= k_min && ok.k <= rows.len() / 2);
    assert!(ok.radius.is_finite() && ok.radius > 0.0);
}

#[test]
fn repeated_construction_is_bit_identical() {
    let rows = three_blobs(10, 10);
    let a = condense(&rows, 3407);
    let b = condense(&rows, 3407);
    assert_eq!(a.optimal_k.k, b.optimal_k.k);
    assert_eq!(a.optimal_k.intrinsic_dim, b.optimal_k.intrinsic_dim);
    assert_eq!(a.optimal_k.radius.to_bits(), b.optimal_k.radius.to_bits());
    assert_eq!(a.assignments, b.assignments);
    for (ca, cb) in a.centroids.iter().zip(&b.centroids) {
        for (xa, xb) in ca.iter().zip(cb) {
            assert_eq!(xa.to_bits(), xb.to_bits());
        }
    }
}

#[test]
fn condense_respects_empty_input_and_k_cap() {
    assert!(condense(&[], 3407).assignments.is_empty());
    // k can never exceed n.
    let rows = vec![vec![0.0], vec![1.0]];
    let basins = condense(&rows, 3407);
    assert!(basins.centroids.len() <= rows.len());
}

