//! Basin condensation — sequential normative port of the arrowspace-rs
//! 0.26.10 optimal-k heuristics (`arrowspace::clustering`), per
//! `docs/specs/09-spectral-array.md` §Basin condensation. Deterministic:
//! base seed 3407 by house law; derived seeds keep upstream derivations.
//! The self-hosting IR-graph path must reproduce this module bit-for-bit.

use rand::SeedableRng;
use rand::rngs::StdRng;
use rand::seq::SliceRandom;
use smartcore::cluster::kmeans::{KMeans, KMeansParameters};
use smartcore::linalg::basic::matrix::DenseMatrix;

/// House base seed for every sampling decision in condensation.
pub const BASE_SEED: u64 = 3407;

const MAX_ITER: usize = 20;
const CH_TRIALS: usize = 3;
const CH_PENALTY: f64 = 0.8;

pub struct OptimalK {
    pub k: usize,
    pub radius: f64,
    pub intrinsic_dim: usize,
}

pub struct Basins {
    pub assignments: Vec<usize>,
    pub centroids: Vec<Vec<f64>>,
    pub optimal_k: OptimalK,
}

/// Lloyd k-means over `rows`, mirroring upstream `kmeans_lloyd`
/// (smartcore KMeans, seeded).
pub fn kmeans_lloyd(rows: &[Vec<f64>], k: usize, max_iter: usize, seed: u64) -> Vec<usize> {
    if rows.is_empty() {
        return Vec::new();
    }
    let (n, f) = (rows.len(), rows[0].len());
    let k = k.min(n);
    let x: DenseMatrix<f64> =
        DenseMatrix::from_iterator(rows.iter().flatten().copied(), n, f, 1);
    let params = KMeansParameters {
        k,
        max_iter,
        seed: Some(seed),
    };
    let km = KMeans::fit(&x, params).expect("Failed to fit K-Means model");
    km.predict(&x).expect("Failed to predict labels")
}

/// Optimal-k heuristic chain: Two-NN bounds, penalized
/// Calinski-Harabasz sweep, pilot radius.
pub fn compute_optimal_k(rows: &[Vec<f64>], base_seed: u64) -> OptimalK {
    if rows.is_empty() {
        return OptimalK {
            k: 0,
            radius: 0.0,
            intrinsic_dim: 0,
        };
    }
    let n = rows.len();
    let f = rows[0].len();
    let (k_min, k_max, id_est) = step1_bounds(rows, n, f, base_seed);

    let sample_size = n.min(1000);
    let sampled_rows: Vec<Vec<f64>> = if n > sample_size {
        let mut rng = StdRng::seed_from_u64(base_seed);
        let mut idxs: Vec<usize> = (0..n).collect();
        idxs.shuffle(&mut rng);
        idxs[..sample_size].iter().map(|&i| rows[i].clone()).collect()
    } else {
        rows.to_vec()
    };

    let k_optimal = step2_calinski_harabasz(&sampled_rows, k_min, k_max, base_seed);
    let radius = compute_threshold_from_pilot(&sampled_rows, k_optimal, base_seed);
    OptimalK {
        k: k_optimal,
        radius,
        intrinsic_dim: id_est,
    }
}

/// Basin condensation: optimal-k heuristics plus one final Lloyd run
/// over all N rows at k* (seed `base_seed`). Centroids of empty
/// clusters stay zero vectors.
pub fn condense(rows: &[Vec<f64>], base_seed: u64) -> Basins {
    if rows.is_empty() {
        return Basins {
            assignments: Vec::new(),
            centroids: Vec::new(),
            optimal_k: compute_optimal_k(rows, base_seed),
        };
    }
    let ok = compute_optimal_k(rows, base_seed);
    let assignments = kmeans_lloyd(rows, ok.k, MAX_ITER, base_seed);

    let f = rows[0].len();
    let mut centroids = vec![vec![0.0f64; f]; ok.k];
    let mut counts = vec![0usize; ok.k];
    for (row, &c) in rows.iter().zip(&assignments) {
        if c < ok.k {
            counts[c] += 1;
            for (cj, val) in centroids[c].iter_mut().enumerate() {
                *val += row[cj];
            }
        }
    }
    for (centroid, &count) in centroids.iter_mut().zip(&counts) {
        if count > 0 {
            for val in centroid.iter_mut() {
                *val /= count as f64;
            }
        }
    }

    Basins {
        assignments,
        centroids,
        optimal_k: ok,
    }
}

fn step1_bounds(
    rows: &[Vec<f64>],
    n: usize,
    f: usize,
    base_seed: u64,
) -> (usize, usize, usize) {
    let id_est = estimate_intrinsic_dimension(rows, n, f, base_seed);

    let k_min = ((n as f64 / 10.0).sqrt().ceil() as usize).max(2);

    // No JL projection in scope: cap at 1000 to prevent high-D explosion.
    let dim_for_bounds = f.min(1000);

    let k_max_candidates = [
        dim_for_bounds * 2,
        n / 10,
        5 * id_est,
        (n as f64).powf(0.5) as usize,
    ];
    let k_max = k_max_candidates
        .iter()
        .copied()
        .min()
        .unwrap_or(k_min + 1)
        .max(k_min + 1)
        .min(n / 2);

    (k_min, k_max, id_est)
}

/// Intrinsic dimension via the Two-NN ratio method (deterministic).
fn estimate_intrinsic_dimension(
    rows: &[Vec<f64>],
    n: usize,
    f: usize,
    base_seed: u64,
) -> usize {
    if n < 10 {
        return f.min(2);
    }

    let sample_size = n.min(500);
    let mut rng = StdRng::seed_from_u64(base_seed.wrapping_add(1));
    let mut indices: Vec<usize> = (0..n).collect();
    indices.shuffle(&mut rng);
    let sample_indices = &indices[..sample_size];

    let mut ratios: Vec<f64> = Vec::new();
    for &i in sample_indices {
        let row_i = &rows[i];
        let mut dists: Vec<(usize, f64)> = (0..n)
            .filter(|&j| j != i)
            .map(|j| {
                let d2: f64 = row_i
                    .iter()
                    .zip(&rows[j])
                    .map(|(a, b)| (a - b) * (a - b))
                    .sum();
                (j, d2.sqrt())
            })
            .collect();
        dists.sort_by(|a, b| a.1.total_cmp(&b.1));
        if dists.len() >= 2 {
            let d1 = dists[0].1;
            let d2 = dists[1].1;
            if d1 > 1e-12 {
                ratios.push(d2 / d1);
            }
        }
    }

    if ratios.is_empty() {
        return f.min(3);
    }

    let mean_ratio: f64 = ratios.iter().sum::<f64>() / ratios.len() as f64;
    let id = if mean_ratio > 1.001 {
        1.0 / mean_ratio.ln()
    } else {
        f as f64
    };
    (id.round() as usize).clamp(1, f)
}

fn step2_calinski_harabasz(
    rows: &[Vec<f64>],
    k_min: usize,
    k_max: usize,
    base_seed: u64,
) -> usize {
    let n = rows.len();
    if n < 10 {
        return k_min;
    }

    let k_range = k_max - k_min;
    let k_step = if k_range <= 5 {
        1
    } else if k_range <= 15 {
        2
    } else {
        3
    };

    let candidates: Vec<usize> = (k_min..=k_max).step_by(k_step).collect();

    let scored = score_candidates(rows, &candidates, base_seed, 1000);

    // Deterministic max; ties prefer larger k.
    let (mut best_k, mut best_score) =
        pick_best(&scored).unwrap_or((k_min, f64::NEG_INFINITY));

    if k_step > 1 {
        let fine_range: Vec<usize> = [
            best_k.saturating_sub(k_step - 1),
            best_k.saturating_sub(1),
            best_k,
            (best_k + 1).min(k_max),
            (best_k + k_step - 1).min(k_max),
        ]
        .into_iter()
        .filter(|&k| k >= k_min && k <= k_max && k < n && !candidates.contains(&k))
        .collect();

        let fine_scored = score_candidates(rows, &fine_range, base_seed, 10000);
        if let Some((fine_k, fine_score)) = pick_best(&fine_scored) {
            if fine_score > best_score {
                best_k = fine_k;
                best_score = fine_score;
            }
        }
    }

    if best_k < k_max {
        best_k
    } else {
        k_max
    }
}

/// Best-of-three Lloyd trials per candidate k, penalized by
/// `CH_PENALTY * k * ln(n)`. Seed stride distinguishes sweep (1000)
/// from fine-tune (10000), matching upstream derivations.
fn score_candidates(
    rows: &[Vec<f64>],
    candidates: &[usize],
    base_seed: u64,
    stride: u64,
) -> Vec<(usize, f64)> {
    let n = rows.len();
    candidates
        .iter()
        .copied()
        .filter(|&k| k < n && k >= 2)
        .map(|k| {
            let mut best_ch = f64::NEG_INFINITY;
            for trial in 0..CH_TRIALS {
                let trial_seed = base_seed
                    .wrapping_add((k as u64) * stride)
                    .wrapping_add(trial as u64);
                let assignments = kmeans_lloyd(rows, k, MAX_ITER, trial_seed);
                best_ch = best_ch.max(calinski_harabasz_score(rows, &assignments, k));
            }
            let penalized = best_ch - CH_PENALTY * (k as f64) * (n as f64).ln();
            (k, penalized)
        })
        .collect()
}

fn pick_best(scored: &[(usize, f64)]) -> Option<(usize, f64)> {
    scored.iter().fold(None, |acc: Option<(usize, f64)>, &(k, s)| {
        Some(match acc {
            None => (k, s),
            Some((bk, bs)) => {
                if s > bs || (s == bs && k > bk) {
                    (k, s)
                } else {
                    (bk, bs)
                }
            }
        })
    })
}

fn calinski_harabasz_score(rows: &[Vec<f64>], assignments: &[usize], k: usize) -> f64 {
    let n = rows.len();
    let f = rows[0].len();

    if k <= 1 || k >= n {
        return 0.0;
    }

    let global_centroid: Vec<f64> = (0..f)
        .map(|j| rows.iter().map(|row| row[j]).sum::<f64>() / n as f64)
        .collect();

    let mut centroids: Vec<Vec<f64>> = vec![vec![0.0; f]; k];
    let mut counts: Vec<usize> = vec![0; k];
    for (i, row) in rows.iter().enumerate() {
        let c = assignments[i];
        if c < k {
            counts[c] += 1;
            for (j, val) in row.iter().enumerate() {
                centroids[c][j] += val;
            }
        }
    }
    for (centroid, &count) in centroids.iter_mut().zip(&counts) {
        if count > 0 {
            for val in centroid.iter_mut() {
                *val /= count as f64;
            }
        }
    }

    let bgss: f64 = centroids
        .iter()
        .zip(&counts)
        .filter(|&(_, &count)| count > 0)
        .map(|(centroid, &count)| {
            let d2: f64 = centroid
                .iter()
                .zip(&global_centroid)
                .map(|(a, b)| (a - b) * (a - b))
                .sum();
            count as f64 * d2
        })
        .sum();

    let wgss: f64 = assignments
        .iter()
        .enumerate()
        .filter(|&(_, &c)| c < k)
        .map(|(i, &c)| {
            rows[i]
                .iter()
                .zip(&centroids[c])
                .map(|(a, b)| (a - b) * (a - b))
                .sum::<f64>()
        })
        .sum();

    if wgss < 1e-10 {
        return 0.0;
    }

    (bgss / (k - 1) as f64) / (wgss / (n - k) as f64)
}

fn compute_threshold_from_pilot(rows: &[Vec<f64>], k: usize, base_seed: u64) -> f64 {
    let assignments = kmeans_lloyd(rows, k, MAX_ITER, base_seed.wrapping_add(100000));
    let f = rows[0].len();

    let mut centroids: Vec<Vec<f64>> = vec![vec![0.0; f]; k];
    let mut counts: Vec<usize> = vec![0; k];
    for (i, row) in rows.iter().enumerate() {
        let c = assignments[i];
        if c < k {
            counts[c] += 1;
            for (j, val) in row.iter().enumerate() {
                centroids[c][j] += val;
            }
        }
    }
    for (centroid, &count) in centroids.iter_mut().zip(&counts) {
        if count > 0 {
            for val in centroid.iter_mut() {
                *val /= count as f64;
            }
        }
    }

    let mut dists: Vec<f64> = assignments
        .iter()
        .enumerate()
        .filter(|&(_, &c)| c < k)
        .map(|(i, &c)| {
            rows[i]
                .iter()
                .zip(&centroids[c])
                .map(|(a, b)| (a - b) * (a - b))
                .sum()
        })
        .collect();

    if dists.is_empty() {
        return 1.0;
    }

    dists.sort_by(|a, b| a.total_cmp(b));
    let percentile_90_idx = ((dists.len() as f64 * 0.9).ceil() as usize).min(dists.len() - 1);
    let percentile_90 = dists[percentile_90_idx];

    let inter_dists: Vec<f64> = (0..k)
        .flat_map(|i| {
            ((i + 1)..k)
                .filter(move |&j| counts[i] > 0 && counts[j] > 0)
                .map(move |j| {
                    centroids[i]
                        .iter()
                        .zip(&centroids[j])
                        .map(|(a, b)| (a - b) * (a - b))
                        .sum()
                })
        })
        .collect();

    let min_inter_centroid_dist2 = inter_dists
        .iter()
        .copied()
        .fold(f64::INFINITY, f64::min);

    let threshold_ratio =
        if min_inter_centroid_dist2.is_finite() && min_inter_centroid_dist2 > 0.0 {
            percentile_90 / min_inter_centroid_dist2
        } else {
            1.0
        };

    if percentile_90 < 1e-8 || threshold_ratio < 0.01 {
        if !inter_dists.is_empty() {
            return (min_inter_centroid_dist2 * 0.15).max(1e-6);
        }
        return 1e-6;
    }

    (percentile_90 * 1.5).max(1e-6)
}

